INSERT INTO visitas (id, notificacion_id, migrated_from_glide, resultado, observaciones, ubicacion_lat, ubicacion_lng, foto_url, fecha) VALUES ('cf1d0bc3-bb5d-457d-875d-468159b6ea50', '9d6c9d78-54ae-4852-8f76-c5c7d980c3d6', 1, 'No Atiende', 'Vecino me informan que el destinatario hace muchos años vivió vendió toda la propiedad y en lo que era la propiedad del mismo existen construida aproximadamente siete viviendas por lo que procedo a dejar en la casa que menos complicación tuve Por cuánto es un barrio sumamente peligroso y hay la presencia de varios masculinos en estado de ebriedad y drogados este dando vuelta amenazándome por lo que procedo a dejar en el primer lugar que forma parte del inmueble donde vivía antes la destinatario', NULL, NULL, 'https://storage.googleapis.com/glide-prod.appspot.com/uploads-v2/1hfcSKizDmCWbiikjxDb/pub/kIKQq7VIRcebWgaMk18Z.jpg', '2025-11-05 17:08:52');
INSERT INTO visitas (id, notificacion_id, migrated_from_glide, resultado, observaciones, ubicacion_lat, ubicacion_lng, foto_url, fecha) VALUES ('951638fc-8e3b-4532-9a96-46dfd4ce3cb9', '9d6c9d78-54ae-4852-8f76-c5c7d980c3d6', 1, 'No Atiende', NULL, NULL, NULL, NULL, '2025-11-05 17:09:00');
INSERT INTO visitas (id, notificacion_id, migrated_from_glide, resultado, observaciones, ubicacion_lat, ubicacion_lng, foto_url, fecha) VALUES ('fe77663e-b103-4bb3-acea-c8a331ac87b0', '9d6c9d78-54ae-4852-8f76-c5c7d980c3d6', 1, 'No Atiende', NULL, NULL, NULL, NULL, '2025-11-05 17:23:37');
INSERT INTO visitas (id, notificacion_id, migrated_from_glide, resultado, observaciones, ubicacion_lat, ubicacion_lng, foto_url, fecha) VALUES ('6a58506c-bc9c-4731-bc6e-83bb77a4c339', '9d6c9d78-54ae-4852-8f76-c5c7d980c3d6', 1, 'No Atiende', 'Por averiguaciones recabadas en la zona los vecinos me informan que el destinatario hace más de 7 años no vive en el lugar y que la propiedad donde vivía La vendió actualmente existen ocho vivienda construida en lo que era la propiedad que pertenecía al destinatario por lo que ningunas de las personas que ocupaban las viviendas me quiso recibir debido a ello y tratándose de una zona sumamente peligrosa habida cuenta que había la existencia de varios masculinos en estado de ebriedad y drogados dando vuelta y amenazándome es que procedo a dejar copia por debajo de la puerta en una de las viviendas que fue construida en la propiedad que pertenecía al destinatario así también me informa que el mismo se encontraría viviendo en la provincia de Mendoza', NULL, NULL, NULL, '2025-11-05 17:28:08');
