INSERT INTO visitas (id, notificacion_id, migrated_from_glide, resultado, observaciones, ubicacion_lat, ubicacion_lng, foto_url, fecha) VALUES ('d1565cc5-1945-4d0f-b60e-82680603f9b6', 'a7e41e53-9167-449d-829c-d8e683577fc4', 1, 'Domicilio Inexistente', 'Me constituí en calle Echeverría altura 600 entre tucumán y salta pudiendo contratar que el número no se encuentra visible es inexistente. En la cuadra existe una fábrica denominada indecat que vende ropa deportiva, luego continúa un galpón que tiene al costado un gabinete que dice bomberos y portón de chapa color celeste lugar que se encontraría deshabitado , y posteriormente sigue una casa identificada con el número 617 y allí termina la cuadra. Al recabar información en la fábrica rmencionada manifiestan no conocer al destinatario, al igual que el unico vecinos que hay en el lugar. Debido a ello devuelvo mandamiento sin diligenciar', NULL, NULL, 'https://storage.googleapis.com/glide-prod.appspot.com/uploads-v2/1hfcSKizDmCWbiikjxDb/pub/2Q64NlsHsuP7pOhF28kY.jpg', '2025-12-09 12:58:00');
INSERT INTO visitas (id, notificacion_id, migrated_from_glide, resultado, observaciones, ubicacion_lat, ubicacion_lng, foto_url, fecha) VALUES ('82182e47-9c03-43f1-8b7a-9548c96b26e7', 'f02643d5-c970-4b45-b53b-b56eee08ef78', 1, 'Domicilio Inexistente', 'Me constituí en calle rivadavia altura 00 al 100 entre avenida belgrano y calle Perú pudiendo constatar que el número 27 no se encuentra visible por lo que procedí a recabar información a vecinos que me manifiestan no conocer a la persona a notificar estan invisible los números 23, 31 , 41 y otros', NULL, NULL, NULL, '2025-12-09 13:12:59');
